// Your backend, with an organization key (never in the browser)
const platform = new SendLit({ apiKey: process.env.SENDLIT_ORG_API_KEY });

const team = await platform.provisioning.provisionTeam({
  externalId: workspace.id,          // an immutable ID from your database
  name: workspace.name,
  sender: { fromName: workspace.name, replyTo: workspace.supportEmail },
  mailingAddress: workspace.address,
  quota: { dailyLimit: 500, monthlyLimit: 10000 },
});

if (team.created) {
  // The plaintext team key is returned once. Encrypt and store it.
  await saveTeamKey(workspace.id, team.teamId, team.apiKey);
}

